import type { FC, ReactNode } from 'react';
import { Download } from 'lucide-react';

interface ProcessResultProps {
  hasFile: boolean;
  blob: Blob | null;
  fileName: string;
  isProcessing: boolean;
  processingLabel: string;
  error: string | null;
  canGenerate: boolean;
  generateLabel: string;
  generateIcon: ReactNode;
  onGenerate: () => void;
  /** e.g. "1.2 MB → 400 KB (67% smaller)" — shown next to the download button once done. */
  summary?: ReactNode;
}

// Shared by Protect/Unlock/Compress PDF — same shape as the other PDF tools'
// results: explicit generate button (not reactive), progress, error, done.
const ProcessResult: FC<ProcessResultProps> = ({
  hasFile,
  blob,
  fileName,
  isProcessing,
  processingLabel,
  error,
  canGenerate,
  generateLabel,
  generateIcon,
  onGenerate,
  summary,
}) => {
  const handleDownload = () => {
    if (!blob) return;
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = fileName;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
  };

  if (error) {
    return (
      <div className="glass-panel p-6 space-y-3">
        <p className="text-sm text-destructive" role="alert">
          {error}
        </p>
        <button
          type="button"
          onClick={onGenerate}
          disabled={!canGenerate}
          className="inline-flex items-center justify-center gap-2 px-4 py-2.5 rounded-lg text-sm font-medium bg-accent text-accent-foreground hover:bg-accent/90 transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
        >
          {generateIcon}
          Try again
        </button>
      </div>
    );
  }

  if (isProcessing) {
    return (
      <div className="glass-panel p-6 flex items-center gap-3" role="status" aria-live="polite">
        <div className="w-4 h-4 rounded-full border-2 border-accent border-t-transparent animate-spin shrink-0" />
        <p className="text-sm text-muted-foreground">{processingLabel}</p>
      </div>
    );
  }

  if (!hasFile) {
    return null;
  }

  if (!blob) {
    return (
      <div className="glass-panel p-6 flex items-center justify-between gap-4 flex-wrap">
        <p className="text-sm text-muted-foreground">Ready when you are.</p>
        <button
          type="button"
          onClick={onGenerate}
          disabled={!canGenerate}
          className="inline-flex items-center justify-center gap-2 px-4 py-2.5 rounded-lg text-sm font-medium bg-accent text-accent-foreground hover:bg-accent/90 transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
        >
          {generateIcon}
          {generateLabel}
        </button>
      </div>
    );
  }

  return (
    <div className="glass-panel hover:border-border p-4 md:p-6 flex items-center justify-between gap-4 flex-wrap">
      {summary ?? <p className="text-sm font-medium text-foreground">Done</p>}
      <button
        type="button"
        onClick={handleDownload}
        className="inline-flex items-center justify-center gap-2 px-4 py-2.5 rounded-lg text-sm font-medium bg-accent text-accent-foreground hover:bg-accent/90 transition-colors"
      >
        <Download className="w-4 h-4" />
        Download PDF
      </button>
    </div>
  );
};

export default ProcessResult;
