import type { FC, ReactNode } from 'react';
import { useCoiServiceWorker } from '@/hooks/useCoiServiceWorker';

// Wraps the PDF unlock/protect/compress tools, which all need the isolation
// useCoiServiceWorker sets up before qpdf-wasm can run at all. See that hook
// for why — this just renders a loading state until it's ready.
const SetupGate: FC<{ children: ReactNode }> = ({ children }) => {
  const ready = useCoiServiceWorker();

  if (!ready) {
    return (
      <div className="glass-panel p-6 flex items-center justify-center text-sm text-muted-foreground min-h-[104px]">
        Setting up secure processing…
      </div>
    );
  }

  return <>{children}</>;
};

export default SetupGate;
