import { useEffect, useState } from 'react';

let scriptInjected = false;

/** Ensures self.crossOriginIsolated is true, which the pthread-enabled qpdf-wasm build
 * requires to run at all. GitHub Pages can't set the Cross-Origin-Opener-Policy /
 * Cross-Origin-Embedder-Policy response headers this normally needs, so
 * coi-serviceworker.js (public/coi-serviceworker.js) adds them client-side instead by
 * intercepting fetches through a service worker.
 *
 * Only called from the pages that actually need it (PDF unlock/protect/compress) —
 * not site-wide — so nobody pays this cost unless they visit one of those tools. The
 * very first activation on a given browser triggers one or two automatic page reloads
 * (inherent to how service worker activation works, not something we control); callers
 * should show a loading state while this returns false. */
export function useCoiServiceWorker(): boolean {
  const [ready, setReady] = useState(() => typeof window !== 'undefined' && window.crossOriginIsolated === true);

  useEffect(() => {
    if (ready) return;

    if (!scriptInjected) {
      scriptInjected = true;
      const script = document.createElement('script');
      script.src = '/coi-serviceworker.js';
      document.head.appendChild(script);
    }

    // coi-serviceworker.js reloads the page itself once isolation is active, so this
    // component just remounts fresh with crossOriginIsolated already true — this poll
    // is a safety net for the (rare) case that doesn't happen, e.g. service workers
    // unsupported or blocked by the browser.
    const interval = window.setInterval(() => {
      if (window.crossOriginIsolated) {
        setReady(true);
        window.clearInterval(interval);
      }
    }, 300);

    return () => window.clearInterval(interval);
  }, [ready]);

  return ready;
}
