import initQpdf from 'qpdf-wasm';
import qpdfWasmUrl from 'qpdf-wasm/qpdf.wasm?url';
// The pthread build spawns workers that load this same script again (checking
// self.name.startsWith('em-pthread') at the bottom of the file to know it's in a
// worker) — locateFile below needs a real URL for that self-reference too, not just
// the .wasm binary. Importing the raw, untransformed file via ?url (rather than
// relying on the normal `initQpdf` import above, which Vite bundles into its own
// chunk under a different identity) gives the worker back the exact same file it
// expects to load.
import qpdfJsUrl from 'qpdf-wasm/qpdf.js?url';

export class QpdfError extends Error {}

// qpdf exit codes: 0 = success, 3 = succeeded with warnings (still produced valid
// output) — anything else is a real failure (bad password, corrupt file, etc).
const OK_EXIT_CODES = new Set([0, 3]);

/** Runs a single qpdf CLI invocation entirely in the browser via WASM — the PDF
 * never leaves the tab. A fresh module instance is created per call rather than
 * reused, since qpdf's C++ globals aren't guaranteed to reset cleanly between runs.
 * Reference the input/output files as the literal strings '{in}' / '{out}' in `args`. */
export async function runQpdf(inputBytes: Uint8Array, args: string[]): Promise<Uint8Array> {
  const stderr: string[] = [];

  const Module = await initQpdf({
    locateFile: (path: string, prefix: string) => {
      if (path.endsWith('.wasm')) return qpdfWasmUrl;
      if (path.endsWith('.js')) return qpdfJsUrl;
      return prefix + path;
    },
    noInitialRun: true,
    print: () => {},
    printErr: (line: string) => stderr.push(line),
  });

  const inPath = '/in.pdf';
  const outPath = '/out.pdf';
  const finalArgs = args.map((a) => (a === '{in}' ? inPath : a === '{out}' ? outPath : a));

  Module.FS.writeFile(inPath, inputBytes);

  let exitCode: number;
  try {
    exitCode = Module.callMain(finalArgs);
  } catch (e) {
    throw new QpdfError(stderr.join('\n') || String(e));
  }

  if (!OK_EXIT_CODES.has(exitCode)) {
    throw new QpdfError(stderr.join('\n') || `qpdf exited with code ${exitCode}`);
  }

  try {
    return Module.FS.readFile(outPath);
  } catch {
    throw new QpdfError(stderr.join('\n') || "qpdf didn't produce an output file");
  }
}
